def skill():
    k, d = -2, 3
    S = Fraction(abs(k)*d**3, 6)
    return int(6*S)

def standard():
    x = Symbol('x')
    h = expand((4)*x**0+(-2)*x**1+(-2)*x**2)
    pts = [Integer(-2)] + sorted(set(r for r in solve(h, x) if r.is_real and -2 < r < 1)) + [Integer(1)]
    tot = 0
    for p_, q_ in zip(pts, pts[1:]):
        tot += Abs(integrate(h, (x, p_, q_)))
    tot = tot*Rational(6, 1)
    return int(tot)

def unique():
    return [standard()]
